&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;PhD in Flight Dynamics, Control oder Autonomy.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;
&lt;p&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;Loitering Munitions oder Live-Warhead Kampagnenerfahrung.&lt;/span&gt;&lt;/p&gt;
